-- Migration 001: initial LAN runtime, independent from the read-only catalog.
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, alias_normalized TEXT UNIQUE NOT NULL, role TEXT NOT NULL CHECK(role IN ('client','operator')), password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, password_parameters TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT UNIQUE NOT NULL, transport TEXT NOT NULL CHECK(transport IN ('cookie','bearer')), csrf_token TEXT, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS login_attempts(alias_normalized TEXT NOT NULL, ip TEXT NOT NULL, occurred_at TEXT NOT NULL, succeeded INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS login_alias ON login_attempts(alias_normalized,occurred_at);
CREATE INDEX IF NOT EXISTS login_ip ON login_attempts(ip,occurred_at);
CREATE TABLE IF NOT EXISTS profiles(user_id TEXT PRIMARY KEY REFERENCES users(id), version INTEGER NOT NULL DEFAULT 1, preferences_version INTEGER NOT NULL DEFAULT 1, completed INTEGER NOT NULL DEFAULT 0, last_completed_step TEXT, service_start_date TEXT, diet TEXT NOT NULL DEFAULT 'omnivore' CHECK(diet IN ('omnivore','vegetarian','vegan')), repetition_tolerance TEXT NOT NULL DEFAULT 'normal' CHECK(repetition_tolerance IN ('low','normal','high')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_allergens(user_id TEXT NOT NULL REFERENCES users(id), allergen_code TEXT NOT NULL, PRIMARY KEY(user_id,allergen_code));
CREATE TABLE IF NOT EXISTS excluded_ingredients(user_id TEXT NOT NULL REFERENCES users(id), ingredient_code TEXT NOT NULL, PRIMARY KEY(user_id,ingredient_code));
CREATE TABLE IF NOT EXISTS ingredient_preferences(user_id TEXT NOT NULL REFERENCES users(id), ingredient_code TEXT NOT NULL, weight INTEGER CHECK(weight IN(-1,1)), PRIMARY KEY(user_id,ingredient_code));
CREATE TABLE IF NOT EXISTS category_preferences(user_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL, PRIMARY KEY(user_id,category));
CREATE TABLE IF NOT EXISTS weekly_calendars(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),effective_month TEXT NOT NULL,revision INTEGER NOT NULL,created_at TEXT NOT NULL, UNIQUE(user_id,effective_month,revision));
CREATE TABLE IF NOT EXISTS weekly_slots(calendar_id TEXT NOT NULL REFERENCES weekly_calendars(id),weekday INTEGER CHECK(weekday BETWEEN 1 AND 7),meal_slot TEXT CHECK(meal_slot IN('desayuno','comida','merienda','cena')),PRIMARY KEY(calendar_id,weekday,meal_slot));
CREATE TABLE IF NOT EXISTS onboarding_drafts(user_id TEXT PRIMARY KEY REFERENCES users(id),fields_json TEXT NOT NULL,last_completed_step TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plan_memberships(user_id TEXT PRIMARY KEY REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1,current_plan TEXT NOT NULL DEFAULT 'free' CHECK(current_plan IN('free','pro')),pending_plan TEXT CHECK(pending_plan IN('free','pro')),effective_date TEXT);
CREATE TABLE IF NOT EXISTS plan_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),previous_plan TEXT,new_plan TEXT,effective_date TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS delivery_addresses(user_id TEXT PRIMARY KEY REFERENCES users(id),version INTEGER NOT NULL,line1 TEXT NOT NULL,city TEXT NOT NULL,postal_code TEXT NOT NULL,notes TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS menu_cycles(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),month TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','pending_review','approved','expired')),version INTEGER NOT NULL DEFAULT 1,service_start_date TEXT NOT NULL,proposal_generation_id TEXT,latest_attempt_id TEXT,published_at TEXT, UNIQUE(user_id,month));
CREATE TABLE IF NOT EXISTS generation_attempts(id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL REFERENCES menu_cycles(id),actor_id TEXT NOT NULL REFERENCES users(id),state TEXT NOT NULL CHECK(state IN('queued','running','succeeded','failed','cancelled')),origin TEXT NOT NULL,provider TEXT,model TEXT,input_snapshot_json TEXT NOT NULL,input_hash TEXT NOT NULL,catalog_hash TEXT NOT NULL,proposed_items_json TEXT,warning_json TEXT NOT NULL DEFAULT '[]',error_json TEXT,created_at TEXT NOT NULL,started_at TEXT,finished_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS active_generation ON generation_attempts(cycle_id) WHERE state IN('queued','running');
CREATE TABLE IF NOT EXISTS menu_items(id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL REFERENCES menu_cycles(id),date TEXT NOT NULL,meal_slot TEXT NOT NULL CHECK(meal_slot IN('desayuno','comida','merienda','cena')),recipe_code TEXT NOT NULL,recipe_snapshot_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,compatibility TEXT NOT NULL CHECK(compatibility IN('compatible','needs_attention')),incompatibility_reasons_json TEXT NOT NULL DEFAULT '[]',cancelled INTEGER NOT NULL DEFAULT 0,cancellation_reason TEXT,UNIQUE(cycle_id,date,meal_slot));
CREATE TABLE IF NOT EXISTS initial_reviews(id TEXT PRIMARY KEY,user_id TEXT UNIQUE NOT NULL REFERENCES users(id),cycle_id TEXT UNIQUE NOT NULL REFERENCES menu_cycles(id),operator_id TEXT NOT NULL REFERENCES users(id),approved_cycle_version INTEGER NOT NULL,approved_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS swaps(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES menu_items(id),actor_id TEXT NOT NULL REFERENCES users(id),old_recipe_code TEXT NOT NULL,new_recipe_code TEXT NOT NULL,previous_version INTEGER NOT NULL,resulting_version INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operator_corrections(id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL REFERENCES menu_cycles(id),item_id TEXT NOT NULL REFERENCES menu_items(id),operator_id TEXT NOT NULL REFERENCES users(id),previous_code TEXT NOT NULL,new_code TEXT NOT NULL,created_at TEXT NOT NULL,proposal_version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS feedback(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),item_id TEXT UNIQUE NOT NULL REFERENCES menu_items(id),recipe_code TEXT NOT NULL,rating INTEGER CHECK(rating IN(-1,1)),comment TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deliveries(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),week_start TEXT NOT NULL,scheduled_date TEXT NOT NULL,address_snapshot_json TEXT,items_snapshot_json TEXT,snapshot_taken_at TEXT,cancelled_reason TEXT,UNIQUE(user_id,week_start));
CREATE TABLE IF NOT EXISTS idempotency_operations(user_id TEXT NOT NULL REFERENCES users(id),operation_name TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,state TEXT NOT NULL,result_json TEXT,expires_at TEXT NOT NULL,PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS runtime_info(key TEXT PRIMARY KEY,value TEXT NOT NULL);
